def mix(counts):
    total = sum(counts.values())
    return {k: round(100 * v / total, 1) for k, v in counts.items()}

import math

def plan(peak_hour_counts, iteration_seconds):
    out = {}
    for tx, count in peak_hour_counts.items():
        rate = count / 3600
        out[tx] = {'per_sec': round(rate, 2), 'users': math.ceil(round(rate * iteration_seconds, 9))}
    return out
